package edu.hfut.incidents.service.impl;
import java.util.*;import java.util.regex.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.*;import com.fasterxml.jackson.databind.*;
import edu.hfut.incidents.dao.IncidentMapper;import edu.hfut.incidents.client.DirectoryClient;import edu.hfut.incidents.dto.Context;import edu.hfut.incidents.exception.ApiException;import edu.hfut.incidents.service.*;import static edu.hfut.incidents.security.Identity.*;
@Service public class IncidentServiceImpl implements IncidentService {
 private final IncidentMapper d;private final DirectoryClient users;private final ObjectMapper json;private final RiskAnalysis risk;private final java.util.concurrent.ConcurrentHashMap<Integer,java.util.concurrent.atomic.LongAdder>counts=new java.util.concurrent.ConcurrentHashMap<>();
 public Map<Integer,Long>instanceCounts(){Map<Integer,Long>out=new TreeMap<>();counts.forEach((p,n)->out.put(p,n.sum()));return out;}
 @Value("${P4_INTERNAL_KEY}")String key;@Value("${p4c.disposition.enabled:false}")boolean enabled;
 public IncidentServiceImpl(IncidentMapper d,DirectoryClient u,ObjectMapper j,RiskAnalysis a){this.d=d;users=u;json=j;risk=a;}
 public static Map<String,Object> map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
 public static String now(){return LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));}
 public String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new ApiException(500,"数据序列化失败");}}
 public static String digest(String s){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder r=new StringBuilder();for(byte x:b)r.append(String.format("%02x",x));return r.toString();}catch(Exception e){throw new IllegalStateException();}}
 public Map<String,Object> view(Map<String,Object>row){if(row==null)return null;Map<String,Object>m=new LinkedHashMap<>();row.forEach((k,v)->{Matcher x=Pattern.compile("_([a-z])").matcher(k);StringBuffer b=new StringBuffer();while(x.find())x.appendReplacement(b,x.group(1).toUpperCase());x.appendTail(b);m.put(b.toString(),v);});if(m.containsKey("actions")){try{m.put("actions",json.readValue(m.get("actions")==null?"[]":String.valueOf(m.get("actions")),List.class));}catch(Exception e){throw new ApiException(500,"异常历史记录格式错误");}}return m;}
 private List<Map<String,Object>> views(List<Map<String,Object>>rows){List<Map<String,Object>>r=new ArrayList<>();for(Map<String,Object>x:rows)r.add(view(x));return r;}
 private Context auth(String t,String...roles){if(t==null||t.isEmpty())throw new ApiException(401,"请先登录后再访问系统接口");Context c=users.resolve(key,"Bearer "+t,map("action","identity"));if(c==null||c.unavailable||c.actor==null)throw new ApiException(503,"身份验证服务不可用");counts.computeIfAbsent(c.servedBy,p->new java.util.concurrent.atomic.LongAdder()).increment();require(c,roles);return c;}
 public Object query(String t,String id,boolean analysis,Map<String,String>q){auth(t,"guard","admin");List<Map<String,Object>>rows=views(d.exceptions());if(id!=null){Map<String,Object>x=view(d.incident(id));if(x==null)throw new ApiException(404,"异常事件不存在");return analysis?risk.analyze(x,rows):x;}if(analysis)return risk.analyzeSet(rows);rows.removeIf(x->(!q.getOrDefault("status","").isEmpty()&&!Objects.equals(x.get("status"),q.get("status")))||(!q.getOrDefault("risk","").isEmpty()&&!Objects.equals(x.get("risk"),q.get("risk")))||(!q.getOrDefault("person","").isEmpty()&&!text(x,"person").contains(q.get("person"))));return rows;}
 public Object chat(String t,Map<String,Object>b){Context c=auth(t,"guard","admin");if(!"admin".equals(c.actor.get("role")))throw new ApiException(403,"只有保卫处管理员可以使用异常分析智能体");String q=text(b,"question").trim();if(q.isEmpty())throw new ApiException(400,"请输入要询问的异常分析问题");return risk.dialogue(views(d.exceptions()),q,b.get("history"),b.get("context"));}
 private void audit(Context c,String action,String id){String event="P4C-"+UUID.randomUUID();d.outbox(event,encode(map("eventId",event,"time",now(),"actor",c.actor.get("name"),"role",c.actor.get("role"),"action",action,"target",id)));}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Object disposition(String t,String id,Map<String,Object>b,boolean action,String requestKey){
  Context c=auth(t,"guard","admin");if(!"guard".equals(c.actor.get("role")))throw new ApiException(403,"异常事件处理必须由门岗安保执行");if(!enabled)throw new ApiException(503,"异常处置状态契约等待批准，暂未开放");
  if(action&&text(b,"action").isEmpty())throw new ApiException(400,"处理动作不能为空",map("missing",Collections.singletonList("action")));
  String status=action?(Boolean.FALSE.equals(b.get("close"))?"处理中":"已处理"):text(b,"status");if(!status.isEmpty()&&!Arrays.asList("待处理","处理中","已处理").contains(status))throw new ApiException(400,"异常状态不合法");
  Map<String,Object>x=view(d.lockIncident(id));if(x==null)throw new ApiException(404,"异常事件不存在");String rid=null,hash=digest(encode(new TreeMap<>(b)));
  if(requestKey!=null){if(requestKey.length()>100||requestKey.isEmpty())throw new ApiException(400,"幂等标识不正确");rid=digest(text(c.actor,"id")+":"+id+":"+action+":"+requestKey);Map<String,Object>old=d.request(rid);if(old!=null){if(!hash.equals(old.get("payload_digest")))throw new ApiException(409,"幂等请求内容冲突");try{return json.readValue(String.valueOf(old.get("response")),Map.class);}catch(Exception e){throw new ApiException(500,"幂等结果不可读取");}}}
  String prior=text(x,"status");if(status.isEmpty())status=prior;boolean changed=!status.equals(prior)||!text(b,"note").isEmpty()&&!Objects.equals(b.get("note"),x.get("note"));
  if("已处理".equals(prior)&&(action||changed)||"处理中".equals(prior)&&"待处理".equals(status))throw new ApiException(409,"异常已处理或状态转换不允许");
  if(action||changed){String stamp=now();x.put("status",status);x.put("handler",c.actor.get("name"));x.put("handledAt",stamp);if(!text(b,"note").isEmpty())x.put("note",b.get("note"));if(action){List<Object>a=new ArrayList<>((List<?>)x.get("actions"));a.add(0,map("action",b.get("action"),"handler",c.actor.get("name"),"note",b.getOrDefault("note",""),"createdAt",stamp));x.put("actions",a);}Map<String,Object>write=new LinkedHashMap<>(x);write.put("actions",encode(x.get("actions")));d.updateIncident(write);audit(c,action?"异常处置":"异常状态更新",id);}
  if(rid!=null)d.insertRequest(rid,hash,encode(x));return x;
 }
 public static String normalize(Object s){return s==null?"":String.valueOf(s).trim().toUpperCase(Locale.ROOT).replaceAll("\\s+","");}
 public static boolean active(Map<String,Object>x){return Arrays.asList("生效","启用").contains(text(x,"status").trim());}
 public static boolean matches(Object stored,Object value){String s=normalize(stored),v=normalize(value);if(s.isEmpty()||v.isEmpty())return false;if(s.equals(v))return true;if(!s.contains("*"))return false;StringBuilder p=new StringBuilder("^");for(int i=0;i<s.length();){if(s.charAt(i)=='*'){while(i<s.length()&&s.charAt(i)=='*')i++;p.append("[0-9]+");}else p.append(Pattern.quote(String.valueOf(s.charAt(i++))));}return v.matches(p.append("$").toString());}
 public Object blackList(String t,Map<String,String>q){auth(t,"admin");List<Map<String,Object>>rows=views(d.blacklist());rows.removeIf(x->!active(x)||(!q.getOrDefault("status","").isEmpty()&&!Objects.equals(x.get("status"),q.get("status")))||(!q.getOrDefault("type","").isEmpty()&&!Objects.equals(x.get("type"),q.get("type")))||(!q.getOrDefault("keyword","").isEmpty()&&!text(x,"name").contains(q.get("keyword"))&&!text(x,"credentialNo").contains(q.get("keyword"))&&!text(x,"reason").contains(q.get("keyword"))));return rows;}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Object createBlack(String t,Map<String,Object>b){Context c=auth(t,"admin");String type=text(b,"type");if(type.isEmpty())type="限制通行人员";String value=normalize(b.get("credentialNo"));if(value.isEmpty())throw new ApiException(400,"请填写身份证号或车牌号");if(value.contains("*"))throw new ApiException(400,"黑名单身份证号必须完整填写，不能使用星号打码");if(!type.equals("异常车辆")&&!value.matches("[0-9]{17}[0-9X]"))throw new ApiException(400,"黑名单人员身份证号需为完整的 18 位身份证号码");d.lockBlacklist();for(Map<String,Object>x:views(d.blacklist()))if(active(x)&&matches(x.get("credentialNo"),value))throw new ApiException(409,"该身份证号或车牌号已在生效黑名单中");Map<String,Object>x=map("id","B"+UUID.randomUUID().toString().replace("-",""),"name",text(b,"name").isEmpty()?"未命名对象":b.get("name"),"type",type,"credentialNo",value,"reason",b.getOrDefault("reason",""),"status",text(b,"status").isEmpty()?"生效":b.get("status"),"createdAt",now());d.insertBlack(x);audit(c,"新增黑名单",text(x,"id"));return x;}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Object updateBlack(String t,String id,Map<String,Object>b){Context c=auth(t,"admin");String reason=text(b,"removedReason");if(reason.isEmpty())reason=text(b,"removeReason");reason=reason.trim();if("已移出".equals(b.get("status"))&&reason.isEmpty())throw new ApiException(400,"拉出黑名单原因不能为空");d.lockBlacklist();Map<String,Object>x=view(d.black(id));if(x==null)throw new ApiException(404,"黑名单记录不存在");if(b.containsKey("status"))x.put("status",b.get("status"));if(b.containsKey("reason"))x.put("reason",b.get("reason"));if("已移出".equals(b.get("status"))){x.put("removedReason",reason);x.put("removedAt",now());x.put("removedBy",c.actor.get("name"));}d.updateBlack(x);audit(c,"更新黑名单",id);return x;}
 public Map<String,Object>check(Map<String,Object>b,boolean access){List<String>v=new ArrayList<>();if(access){Map<String,Object>p=b.get("person") instanceof Map?(Map)b.get("person"):Collections.emptyMap(),q=b.get("qrCode") instanceof Map?(Map)b.get("qrCode"):Collections.emptyMap();for(String f:Arrays.asList("name","code","idNumber","phone"))if(p.get(f)!=null)v.add(String.valueOf(p.get(f)));for(String f:Arrays.asList("ownerName","token"))if(q.get(f)!=null)v.add(String.valueOf(q.get(f)));if(b.get("credential")!=null)v.add(String.valueOf(b.get("credential")));}else v.add(text(b,"credential"));for(Map<String,Object>x:views(d.blacklist()))if(active(x))for(String value:v)if((access&&!text(x,"name").isEmpty()&&value.equals(text(x,"name")))||matches(x.get("credentialNo"),value))return map("available",true,"blocked",true,"reason",text(x,"reason").isEmpty()?x.get("name"):x.get("reason"));return map("available",true,"blocked",false,"reason","");}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Map<String,Object>accept(Map<String,Object>e){
  Map<String,Object>r=e.get("record") instanceof Map?(Map)e.get("record"):null;Object allow=e.get("allowed");if(r==null||!text(r,"id").matches("R[A-Z0-9]+")||!(allow instanceof Boolean)||!(e.get("reason") instanceof String))throw new ApiException(400,"异常事件参数不正确");
  String id="E"+r.get("id"),hash=digest(encode(map("record",new TreeMap<>(r),"reason",e.get("reason"),"allowed",allow)));d.lockBlacklist();Map<String,Object>old=d.inbox(id);if(old!=null){if(!hash.equals(old.get("payload_digest")))throw new ApiException(409,"异常事件标识内容冲突");return map("accepted",true,"recordId",r.get("id"));}
  if(Boolean.FALSE.equals(allow)){String reason=text(e,"reason"),level=Pattern.compile("黑名单|强行|冒用").matcher(reason).find()?"高风险":Pattern.compile("未找到|不允许|过期|不可用").matcher(reason).find()?"中风险":"低风险";Map<String,Object>x=map("id",id,"time",r.get("time"),"person",r.get("name"),"personType",r.get("type"),"gate",r.get("gate"),"method",r.get("method"),"type",text(r,"method")+"失败","reason",reason,"risk",level,"status","待处理","suggestion",level.equals("高风险")?"建议拒绝通行并立即上报保卫处管理员复核。":"建议门岗核验身份信息并联系相关人员确认，确认无误后可人工核验后放行。","actions","[]");Map<String,Object>existing=d.incident(id);if(existing==null)d.insertIncident(x);else{Map<String,Object>a=view(existing);for(String f:Arrays.asList("time","person","personType","gate","method","type","reason","risk"))if(!Objects.equals(a.get(f),x.get(f)))throw new ApiException(409,"既有异常事件内容冲突");}}
  d.insertInbox(id,hash,Boolean.FALSE.equals(allow)?id:null,now());return map("accepted",true,"recordId",r.get("id"));
 }
 public Map<String,Object>projection(){return map("exceptions",views(d.exceptions()),"blacklist",views(d.blacklist()));}
}
